WITH cleaned AS (SELECT *, UPPER(browser) browser_upper, COALESCE(country, 'OTHER') country_clean FROM sessions WHERE started_at > DATE '2023-04-23' AND HOUR(started_at) BETWEEN 8 AND 16), scored AS (SELECT *, FIRST_VALUE(country) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_country, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('YEAR', started_at), browser ORDER BY started_at DESC, id) row_seq FROM cleaned WHERE device = 'mobile'), enriched AS (SELECT id, customer_id, device, browser_upper, country_clean, first_known_country, row_seq, ROUND(row_seq / SUM(row_seq) OVER (PARTITION BY DATE_TRUNC('YEAR', started_at), browser), 4) row_seq_share, LAG(row_seq, 1, 0) OVER (PARTITION BY device ORDER BY started_at, id) prev_row_seq, MAX(row_seq) OVER (PARTITION BY browser ORDER BY CAST(started_at AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) row_seq_max_7d, LAG(row_seq, 1) OVER w_hist prev_row_seq_2 FROM scored WINDOW w_hist AS (ORDER BY row_seq, id)), with_latest AS (SELECT s.id, s.device, s.browser_upper, s.row_seq, s.row_seq_share, top1.web_event_duration_sec FROM enriched s LEFT JOIN LATERAL (SELECT c.duration_sec AS web_event_duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_windows AS (SELECT id, browser_upper, row_seq_share, web_event_duration_sec, DENSE_RANK() OVER (ORDER BY web_event_duration_sec NULLS FIRST) web_event_duration_sec_dense_rank, ROW_NUMBER() OVER (ORDER BY row_seq_share, id) row_seq_2, AVG(row_seq) OVER (PARTITION BY device ORDER BY web_event_duration_sec, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) row_seq_avg_5 FROM with_latest) SELECT CASE WHEN row_seq_2 >= 8 THEN 'LARGE' ELSE 'SMALL' END AS row_seq_2_tier, CASE WHEN web_event_duration_sec >= 432 THEN 'HIGH' ELSE 'LOW' END AS web_event_duration_sec_tier, PERCENTILE_APPROX(row_seq_avg_5, ARRAY(0.25, 0.5, 0.75)) AS row_seq_avg_5_quartiles, MAX(row_seq_2) AS max_row_seq_2, PERCENTILE_APPROX(row_seq_avg_5, 0.95) AS row_seq_avg_5_p95 FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN row_seq_2 >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN web_event_duration_sec >= 432 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN row_seq_2 >= 8 THEN 'LARGE' ELSE 'SMALL' END)) HAVING MAX(row_seq_2) > 0 ORDER BY row_seq_2_tier NULLS LAST;
